#include <bits/stdc++.h>
using namespace std;

struct Entry {
    int g;
    int count;
    int cumulative;
};

struct Node {
    int length = 0;
    int g = 0;
    long long good = 0;
    vector<Entry> prefix;
    vector<Entry> suffix;
};

void appendEntry(vector<Entry>& v, int g, int count) {
    if (!v.empty() && v.back().g == g) {
        v.back().count += count;
        v.back().cumulative += count;
    } else {
        int cumulative = count + (v.empty() ? 0 : v.back().cumulative);
        v.push_back({g, count, cumulative});
    }
}

long long countShared(const vector<Entry>& a, const vector<Entry>& b) {
    long long result = 0;
    for (const Entry& x : a) {
        int k = 0;
        int n = (int)b.size();

        if (n > 0 && gcd(x.g, b[0].g) > 1) {
            if (gcd(x.g, b[n - 1].g) > 1) {
                k = n;
            } else {
                int lo = 1, hi = n - 1;
                while (lo < hi) {
                    int mid = (lo + hi) / 2;
                    if (gcd(x.g, b[mid].g) > 1)
                        lo = mid + 1;
                    else
                        hi = mid;
                }
                k = lo;
            }
        }

        if (k > 0)
            result += 1LL * x.count * b[k - 1].cumulative;
    }
    return result;
}

Node combine(const Node& a, const Node& b) {
    if (a.length == 0) return b;
    if (b.length == 0) return a;

    Node result;
    result.length = a.length + b.length;
    result.g = gcd(a.g, b.g);
    result.good = a.good + b.good + countShared(a.suffix, b.prefix);

    result.prefix = a.prefix;
    for (const Entry& e : b.prefix)
        appendEntry(result.prefix, gcd(a.g, e.g), e.count);

    result.suffix = b.suffix;
    for (const Entry& e : a.suffix)
        appendEntry(result.suffix, gcd(b.g, e.g), e.count);

    return result;
}

Node makeLeaf(int value) {
    Node node;
    node.length = 1;
    node.g = value;
    node.good = (value > 1);
    node.prefix.push_back({value, 1, 1});
    node.suffix.push_back({value, 1, 1});
    return node;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M;
    cin >> N >> M;

    int base = 1;
    while (base < N) base <<= 1;

    vector<Node> tree(2 * base);
    for (int i = 0; i < N; ++i) {
        int value;
        cin >> value;
        tree[base + i] = makeLeaf(value);
    }

    for (int i = base - 1; i >= 1; --i)
        tree[i] = combine(tree[2 * i], tree[2 * i + 1]);

    while (M--) {
        int type, x, y;
        cin >> type >> x >> y;

        if (type == 1) {
            int p = base + x - 1;
            tree[p] = makeLeaf(y);
            for (p >>= 1; p; p >>= 1)
                tree[p] = combine(tree[2 * p], tree[2 * p + 1]);
        } else {
            int l = base + x - 1;
            int r = base + y;

            Node left, right;
            while (l < r) {
                if (l & 1)
                    left = combine(left, tree[l++]);
                if (r & 1)
                    right = combine(tree[--r], right);
                l >>= 1;
                r >>= 1;
            }

            Node answer = combine(left, right);
            cout << answer.good << '\n';
        }
    }

    return 0;
}
